import 'package:flutter/material.dart';

class VtmDemoStore {
  static final values={'serial':'VTM-DEMO-001','voltage':'12.70','temperature':'25.0','technician':'Demo Technician'};
  static final audit=<String>[]; static final certificates=<String>[];
  static void log(String s)=>audit.add('${DateTime.now().toIso8601String()} — $s');
  static void reset(){values..clear()..addAll({'serial':'VTM-DEMO-001','voltage':'12.70','temperature':'25.0','technician':'Demo Technician'});audit.clear();certificates.clear();log('Demo reset');}
}

class VtmDemoCalibrationScreen extends StatefulWidget { const VtmDemoCalibrationScreen({super.key}); @override State<VtmDemoCalibrationScreen> createState()=>_VtmDemoState(); }
class _VtmDemoState extends State<VtmDemoCalibrationScreen>{ bool passed=false;
  void calibration(){VtmDemoStore.log('Calibration opened');showDialog(context:context,builder:(_)=>AlertDialog(title:const Text('Simulated Calibration'),content:const Text('Demo readings: 12.70 V • 25.0 °C\nCalibration values are simulated.'),actions:[TextButton(onPressed:()=>Navigator.pop(context),child:const Text('Cancel')),FilledButton(onPressed:(){VtmDemoStore.log('Calibration completed');setState(()=>passed=true);Navigator.pop(context);},child:const Text('Complete Calibration'))]));}
  void issue(){if(!passed)return;VtmDemoStore.certificates.add('VTM Calibration Certificate\nDEMO / NOT FOR PRODUCTION USE\nVTM-TEST • ${VtmDemoStore.values['serial']}\nIssued ${DateTime.now()}');VtmDemoStore.log('Demo certificate issued');setState((){});}
  void history()=>showDialog(context:context,builder:(_)=>AlertDialog(title:const Text('Demo Certificate History'),content:SingleChildScrollView(child:Text(VtmDemoStore.certificates.isEmpty?'No demo certificates issued.':VtmDemoStore.certificates.join('\n\n')))));
  @override Widget build(BuildContext context){final t=Theme.of(context);return Scaffold(appBar:AppBar(title:const Text('VTM-TEST Dashboard'),actions:[IconButton(onPressed:(){VtmDemoStore.reset();setState(()=>passed=false);},icon:const Icon(Icons.restart_alt))]),bottomNavigationBar:NavigationBar(selectedIndex:0,destinations:[NavigationDestination(icon:const Icon(Icons.dashboard_outlined),label:'Dashboard'),NavigationDestination(icon:const Icon(Icons.show_chart),label:'Trend'),NavigationDestination(icon:const Icon(Icons.description_outlined),label:'Reports'),NavigationDestination(icon:const Icon(Icons.download_outlined),label:'Download'),NavigationDestination(icon:const Icon(Icons.settings_outlined),label:'Settings')]),body:ListView(padding:const EdgeInsets.all(16),children:[Card(child:ListTile(leading:Icon(Icons.battery_charging_full),title:const Text('Battery Monitoring'),subtitle:const Text('Demo site • Lab bench • VTM-TEST'),trailing:const Chip(avatar:Icon(Icons.circle,size:10,color:Colors.green),label:Text('Demo Online')))),const SizedBox(height:16),LayoutBuilder(builder:(_,b)=>GridView.count(shrinkWrap:true,physics:const NeverScrollableScrollPhysics(),crossAxisCount:b.maxWidth<360?1:2,crossAxisSpacing:12,mainAxisSpacing:12,children:[_battery(t,1,'12.70','25.0'),_battery(t,2,'12.64','25.4')])),const SizedBox(height:20),Text('Trending',style:t.textTheme.titleLarge),const SizedBox(height:8),DropdownButtonFormField<String>(value:'Last 24 Hours',items:const[DropdownMenuItem(value:'Last 24 Hours',child:Text('Last 24 Hours'))],onChanged:null),const SizedBox(height:8),_chart(t,'Voltage','V'),const SizedBox(height:8),_chart(t,'Temperature','°C'),const SizedBox(height:12),Wrap(spacing:8,runSpacing:8,children:[FilledButton.icon(onPressed:calibration,icon:const Icon(Icons.tune),label:const Text('Calibration')),OutlinedButton.icon(onPressed:history,icon:const Icon(Icons.history),label:const Text('Demo Certificate History')),FilledButton.icon(onPressed:passed?issue:null,icon:const Icon(Icons.verified),label:const Text('Issue Demo Certificate'))]),const SizedBox(height:12),Text('Simulated VTM-TEST data • Demo only',style:t.textTheme.bodySmall)]) );}
  Widget _battery(ThemeData t,int n,String v,String temp)=>Card(child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[Container(color:t.colorScheme.primary,padding:const EdgeInsets.all(10),child:Text('🔋 Battery $n (12 V)',style:TextStyle(color:t.colorScheme.onPrimary,fontWeight:FontWeight.bold))),Padding(padding:const EdgeInsets.all(12),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(v,style:t.textTheme.headlineMedium),Text('Voltage • simulated',style:t.textTheme.bodySmall),const SizedBox(height:8),Text('$temp °C',style:t.textTheme.titleLarge),Text('Temperature • simulated',style:t.textTheme.bodySmall),const SizedBox(height:8),const Text('● Healthy',style:TextStyle(color:Colors.green))]))]));
  Widget _chart(ThemeData t,String title,String unit)=>Card(child:Padding(padding:const EdgeInsets.all(12),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('$title ($unit)',style:t.textTheme.titleMedium),SizedBox(height:100,child:CustomPaint(painter:_ChartPainter(t.colorScheme.primary),child:const SizedBox.expand())),Text('■ Battery 1   ■ Battery 2',style:t.textTheme.bodySmall),Text('Simulated 24-hour $title trend',style:t.textTheme.bodySmall)])));
}
class _ChartPainter extends CustomPainter{_ChartPainter(this.color);final Color color;@override void paint(Canvas c,Size s){final p=Paint()..color=color.withOpacity(.18)..strokeWidth=1;for(var i=1;i<5;i++){final y=s.height*i/5;c.drawLine(Offset(0,y),Offset(s.width,y),p);}final line=Paint()..color=color..strokeWidth=3..style=PaintingStyle.stroke;final path=Path()..moveTo(0,s.height*.65)..lineTo(s.width*.2,s.height*.4)..lineTo(s.width*.4,s.height*.55)..lineTo(s.width*.6,s.height*.3)..lineTo(s.width*.8,s.height*.45)..lineTo(s.width,s.height*.25);c.drawPath(path,line);}@override bool shouldRepaint(covariant _ChartPainter old)=>false;}
